def _extract_json_fenced_blocks(text: str, start_re: re.Pattern[str]) -> list[str]:
    blocks: list[str] = []
    for start in start_re.finditer(text):
        content_start = start.end()
        for fence in FENCE_RE.finditer(text, content_start):
            block = text[content_start:fence.start()].strip()
            if not block:
                continue
            try:
                json.loads(block)
            except json.JSONDecodeError:
                repaired = re.sub(r",\s*([}\]])", r"\1", block)
                try:
                    json.loads(repaired)
                except json.JSONDecodeError:
                    continue
            blocks.append(block)
            break
    return blocks
